<template>
<div class='h-28 flex flex-col justify-center items-center mt-14'>
    <div class="flex-shrink-0 group block">
  <div class="flex items-center">
    <img class="inline-block flex-shrink-0 h-4 w-4 rounded-full" :src="iconUser" />
    <div class="ml-1">
      <p class="text-sm font-medium text-gray-500">{{email}}</p>
    </div>
  </div>
</div>
<button 
  class="w-11/12 py-3 px-4 h-10 mt-2 inline-flex justify-center items-center gap-2 rounded-md border 
  font-semibold  text-white hover:border-gray-300  focus:outline-none focus:ring-2 focus:ring-blue-500 focus:ring-offset-2 
  transition-all text-sm dark:focus:ring-offset-gray-800"
  @click="handleLogout"
>
  <img class="inline-block h-4 w-4" :src="iconLogout" alt="Logout Icon" />
  <span class="text-gray-700 font-semibold text-lg">Logout</span>
</button>

  </div>
</template>

<script setup>
import { useAuthStore } from '../../../store/authStore.js'
const iconUser = new URL(`../../../assets/user.png`, import.meta.url).href;
const iconLogout = new URL(`../../../assets/logout.png`, import.meta.url).href;
import { ref, computed } from "vue"; // 请注意此处
const authStore = useAuthStore();
const handleLogout = async () => {
  await authStore.doLogout(); 
  authStore.setActiveTabIndex(0)
};
let email = computed(() => (authStore.user ? authStore.user.email : ""));
</script>

