import JSZip from 'jszip';
import { saveAs } from 'file-saver';
import { SITE } from '../utils/config.js';

async function convertWebPToJPEG(blob) {
    return new Promise((resolve, reject) => {
        const canvas = document.createElement('canvas');
        const ctx = canvas.getContext('2d');
        const img = new Image();
        img.onload = () => {
            canvas.width = img.width;
            canvas.height = img.height;
            ctx.drawImage(img, 0, 0);
            canvas.toBlob(blob => resolve(blob), 'image/jpeg');
        };
        img.onerror = reject;
        img.src = URL.createObjectURL(blob);
    });
}


export async function downloadSingleImage(filename,imageUrl) {
    try {
        const response = await fetch(imageUrl);
        let blob = await response.blob();

        // 检查blob类型是否为webp
        if (blob.type === 'image/webp') {
            blob = await convertWebPToJPEG(blob); // 转换webp到JPEG
        }
        const a = document.createElement('a');
        a.href = URL.createObjectURL(blob);
        a.download = filename;
        document.body.appendChild(a);
        a.click();
        URL.revokeObjectURL(a.href); // 清除创建的URL，避免内存泄漏
        document.body.removeChild(a); // 从文档中移除链接元素
    } catch (error) {
        console.error('download error:', error);
    }
}

export async function downloadImagesZip(goodsId, images, type, progressCallback) {
    const zip = new JSZip();
    let completedTasks = 0;
    const totalTasks = images.length; // 只计算文件处理次数
    const downloadAndProcessShare = 0.9; // 下载和处理占总进度的90%

    // 更新进度的函数
    const updateProgress = (additionalProgress = 0) => {
        const baseProgress = ((completedTasks / totalTasks) * 100 * downloadAndProcessShare) + additionalProgress;
        progressCallback(baseProgress < 100 ? baseProgress : 99);
    };

    // 处理并添加文件到ZIP
    const processAndAddFiles = async () => {
        const folderName = `${SITE}_${type}`
        const fileName = `${SITE}_${type}`
        for (let i = 0; i < images.length; i++) {
            const item = images[i];
            let imgSrc = item
            if (type === 'variant') {
              imgSrc =  item.image
            }
            const response = await fetch(imgSrc);
            let blob = await response.blob();

            if (blob.type === 'image/webp') {
              const jpegBlob = await convertWebPToJPEG(blob);
              zip.file(`${folderName}/${fileName}_${i}.jpeg`, jpegBlob);
            } else {
            //   zip.file(`${fileName}_${i}.${blob.type.split('/')[1]}`, blob);
              zip.file(`${folderName}/${fileName}_${i}.jpeg`, blob);
            }
            completedTasks++;
            updateProgress();
        }
    };

    await processAndAddFiles(); // 确保所有文件都处理并添加到ZIP

    // 生成ZIP文件
    zip.generateAsync({ type: "blob", compression: "STORE" }, metadata => {
        // 压缩进度部分
        const zipProgress = 90 + metadata.percent * 0.1; // 最后10%为压缩进度
        progressCallback(zipProgress);
    }).then(content => {
        saveAs(content, `${SITE}_${type}.zip`);
        progressCallback(100); // 完成
    }).catch(error => {
        console.error("Error during ZIP creation:", error);
        progressCallback(100, "Error"); // 错误处理
    });
}

// utils/downloadUtil.js
export async function downloadVideo(goodsId, index, videoUrl, progressCallback) {
    try {
        const response = await fetch(videoUrl);
        const reader = response.body.getReader();
        const contentLength = +response.headers.get('Content-Length');
        let receivedLength = 0;  // 已接收的字节。
        let chunks = [];  // 接收到的二进制块数组。

        while(true) {
            const {done, value} = await reader.read();
            if (done) {
                break;
            }
            chunks.push(value);
            receivedLength += value.length;
            progressCallback((receivedLength / contentLength) * 100);
        }

        const blob = new Blob(chunks, {type: 'video/mp4'});
        const downloadUrl = window.URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = downloadUrl;
        a.download = `${SITE}_${goodsId}_${index}.mp4`;
        document.body.appendChild(a);
        a.click();
        window.URL.revokeObjectURL(downloadUrl);
        document.body.removeChild(a);
    } catch (error) {
        console.error('Download video failed:', error);
    }
}