<script>
import { usePlanStore } from "../../../store/planStore";
import { useAuthStore } from "../../../store/authStore.js";
import { APP_ID } from '../../../utils/config.js'
export default {
  name: "CustomTable",
  data() {
    return {
      agree: true,
      selectedIndex: 0,
      items: [
       {
          content: ["Download single images", "(*.jpeg) "],
          freeHas: true,
          proHas: true,
        },
        {
          content: ["One Click Download Images", "(*.zip,*.xlsx) "],
          freeHas: false,
          proHas: true,
        },
        {
          content: ["Download Videos", "(*.mp4) "],
          freeHas: false,
          proHas: true,
        },
      ],
      planStore: usePlanStore(),
      store: useAuthStore(),
    };
  },
  computed: {
    data() {
      const planInfo = this.planStore.planInfo;
      if (!planInfo) return { text: "", subs: [] }; // Default values

      return {
        text: planInfo.promo,
        subs: planInfo.plans,
      };
    },
    promoShow() {
      if (this.data.subs && this.data.subs.length > this.selectedIndex) {
        return this.data.subs[this.selectedIndex].pormo_show;
      }
    },
    currentPrice() {
      if (this.data.subs && this.data.subs.length > this.selectedIndex) {
        return this.data.subs[this.selectedIndex].price;
      }
    },
    currentPormo() {
      if (this.data.subs && this.data.subs.length > this.selectedIndex) {
        return this.data.subs[this.selectedIndex].promo;
      }
    },
    currentName() {
      if (this.data.subs && this.data.subs.length > this.selectedIndex) {
        return this.data.subs[this.selectedIndex].name;
      }
    },
    isPro() {
      return this.planStore.pro;
    },
    uid() {
      return this.store.user ? this.store.user.uid : "";
    },
    isCancelled() {
      return this.planStore.planInfo.status == "cancelled";
    },
    // expireDate() {
    //   const date = new Date(this.planStore.planInfo.ends_at);
    //   const year = date.getFullYear();
    //   const month = date.getMonth() + 1; // 月份从 0 开始，所以加 1
    //   const day = date.getDate();
    //   const hour = date.getHours();
    //   const minutes = date.getMinutes();

    //   return `${year}.${month}.${day} ${hour}:${minutes}`;
    // },
  },
  methods: {
    subscribe() {
      if (!this.agree) {
        alert("You have to agree to the Terms Of Service.");
        return;
      }
      const baseUrl = import.meta.env.VITE_PAYOUT_URL;
      const params = {
        plan: this.currentName,
        app: APP_ID,
        uid: this.uid,
        ver: "1.2.0",
      };
      const query = new URLSearchParams(params).toString();
      const urlWithParams = `${baseUrl}?${query}`;

      chrome.tabs.create({ url: urlWithParams });
    },
    unsubscribe() {
      const data = {
        id: this.planStore.planInfo.proId,
      };
      this.planStore.unsubscribe(data);
    },
    openSubscriptionPage() {
      chrome.tabs.create({url: "https://app.lemonsqueezy.com/my-orders"})
    },
    async renew() {
      const data = {
        id: this.planStore.planInfo.proId,
      };
      const rt =  await this.planStore.renew(data)
      if (!rt) {
        //跳到customer portal界面
        console.debug("jump to billing")
        chrome.tabs.create({ url: "https://webstar.lemonsqueezy.com/billing" });
      }
    },
  },
};
</script>

