<script>
import JSZip from 'jszip';
import { saveAs } from 'file-saver';
import * as XLSX from 'xlsx';
import { usePlanStore } from '../../../store/planStore';
import { useAuthStore } from '../../../store/authStore.js'
import { downloadVideo, downloadSingleImage, downloadImagesZip} from '../../../utils/downloadUtil'
import { SITE } from '../../../utils/config.js'

export default {
  data() {
    return {
      planStore: usePlanStore(),
      authStore: useAuthStore(),
      currentTab: 'image',
      videoProgresses: new Array(this.videosCount).fill(-1),
      imageProgresses: new Array(3).fill(-1),
    };
  },
  computed: {
    isVideoDownloading() {
       return (index) => 
       this.videoProgresses[index] >= 0 && this.videoProgresses[index] < 100;
    },
    isImageDownloading() {
       return (index) => 
       this.imageProgresses[index] >= 0 && this.imageProgresses[index] < 100;
    },
    totalImagesCount() {
    return this.productData.mainImages.length + this.productData.categoryImages.length + this.productData.descriptionImages.length;
  },
    productData() {
      var product = this.planStore.product;
      if (!product) return {
        isProduct: false,
        title: "",
        mainImages: [],
        categoryImages: [],
        descriptionImages: [],
      }; // Default values
      return product;
    },
    imagesCount() {
      var product = this.planStore.product;
      if (!product) return 0; // Default values
      return product.mainImages.length + product.categoryImages.length + product.descriptionImages.length; 
    }
  },
  methods: {
  
async convertWebPToJPEG(blob) {
    return new Promise((resolve, reject) => {
        const canvas = document.createElement('canvas');
        const ctx = canvas.getContext('2d');
        const img = new Image();

        img.onload = () => {
            canvas.width = img.width;
            canvas.height = img.height;
            ctx.drawImage(img, 0, 0);
            canvas.toBlob(resolve, 'image/jpeg');
        };

        img.onerror = reject;
        img.src = URL.createObjectURL(blob);
    });
},

async downloadImage(type,index,image) {
  let fileName = 'image'
  if (type === 'variant') {
    // fileName = `${SITE}_${this.productData.title}_${type}_${this.productData.categoryImages[index].name}_${index}`
    fileName = `${SITE}_${type}_${index}`
  } else {
    fileName = `${SITE}_${type}_${index}`
  }
  downloadSingleImage(fileName, image)
},
    async downloadAllImages() {

      if(this.productData.categoryImages.length>0) {
        await this.downloadImagesZip(this.productData.categoryImages, 'variant', 0);
      }

      if(this.productData.mainImages.length>0) {
        await this.downloadImagesZip(this.productData.mainImages, 'main', 1);
      }

      if(this.productData.descriptionImages.length>0) {
        await this.downloadImagesZip(this.productData.descriptionImages, 'desc', 2);
      }
    },

    async downloadVideo(videoUrl, index) {
      if (!this.planStore.pro) {
        this.authStore.activeTabIndex = 3
        return
      }
      this.videoProgresses[index] = 0
      try {
        await downloadVideo(this.productData.title, index, videoUrl, progress => {
          this.videoProgresses[index] = progress
        });
      } catch (error) {
        console.error('Download video failed', error);
      }
   },


    downloadAllExcel() {
      if (!this.planStore.pro) {
        this.authStore.activeTabIndex = 3;
        return
      }
      if (this.productData.categoryImages.length > 0) {
        this.downloadExcel(this.productData.categoryImages, 'variant');
      }
      if (this.productData.mainImages.length > 0) {
        this.downloadExcel(this.productData.mainImages, 'main');
      }
      if (this.productData.descriptionImages.length > 0) {
        this.downloadExcel(this.productData.descriptionImages, 'desc');
      }
    },

    async downloadImagesZip(images, type, index) {
      if (!this.planStore.pro) {
        this.authStore.activeTabIndex = 3
        return
      }
      this.imageProgresses[index] = 0
      try {
        downloadImagesZip(this.productData.title, images, type, progress => {
          this.imageProgresses[index] = progress
        });
      } catch (error) {
        console.error('Download video failed', error);
      }

   },

    downloadExcel(images, type) {
      if (!this.planStore.pro) {
        this.authStore.activeTabIndex = 3;
        return
      }s
      let data;
      if (type === 'variant') {
        data = images.map(img => ({
          // sku: img.sku,
          variant: img.name,
          image: img.image,
          title: this.productData.title
        }));
      } else {
        data = images.map(img => ({ image: img }));
      }
      const worksheet = XLSX.utils.json_to_sheet(data);
      const workbook = XLSX.utils.book_new();
      XLSX.utils.book_append_sheet(workbook, worksheet, type);
      XLSX.writeFile(workbook, `${type}_images.xlsx`);
    },
  }
};
</script>

