// store/auth.js
import { defineStore } from 'pinia';
import { saveToken, getToken, removeToken, getAuthToken, saveUser, getUser, removeUser} from './storage.js'
import {login, logout, getGoogleUserInfo} from '../api/user.js'
import { usePlanStore } from "./planStore.js";
import log from 'loglevel';
import { APP_ID } from '../utils/config.js';

export const useAuthStore = defineStore({
  id: 'auth',
  state: () => ({
    token: null,
    isLoggedIn: false,
    activeTabIndex: 0, // 新增
    isLoading: false,
    user: null
  }),
  actions: {
    setActiveTabIndex(index) { // 新增
      this.activeTabIndex = index;
    },
    async checkLoginStatus() {
      this.user = await getUser();
      if (this.user) {
        this.token = this.user.session_id;
        this.isLoggedIn = !!this.token;
        log.debug("this.token:", this.token)
        log.debug("this.isLoggedIn:", this.isLoggedIn)
      }
    },
    async doLogin(username, password) {
      this.isLoading = true;  // Start loading
      const access_token = await getAuthToken()
      log.debug(access_token);
      let rp = await getGoogleUserInfo({"alt":"json", "access_token": access_token})
      if (rp && !rp.error) {
        const data = await login({"email":rp.email, "password": rp.id, "app_id":APP_ID})
        if (data && data.data) {
        const token = data.data.session_id
        if (token) {
          this.token = token
          this.isLoggedIn = true
          this.user = data.data
          saveUser(data.data)
          //加载planinfo
          const planStore = usePlanStore();
          planStore.getInfo(true);
          }
        }
     } else {
      chrome.identity.removeCachedAuthToken(
        { 'token': access_token },
        null);
     }
     this.isLoading = false;  // End loading
    },
      async doLogout() {
       this.resetLoginStatus()
        logout()
      },
      async resetLoginStatus() {
        this.token = null;
        this.isLoggedIn = false;
        removeUser()
      },
  },
});
