import { createApp } from "vue";
import App from "./App.vue";
import { createPinia } from "pinia";
import { useAuthStore } from "./store/authStore.js";
import { usePlanStore } from "./store/planStore.js";
import { checkNet } from "./utils/request.js";
import log from 'loglevel';


async function init() {
    //set log
    if (import.meta.env.MODE === 'development') {
        log.setLevel(log.levels.DEBUG);
    } else {
        log.setLevel(log.levels.ERROR);
    }
    log.debug("uri", chrome.identity.getRedirectURL())

    const app = createApp(App); 

    const pinia = createPinia();
    app.use(pinia);

    const planStore = usePlanStore();
    chrome.runtime.onMessage.addListener((message, sender, sendResponse) => {
        if (message.action === "sendProductData") {
            log.debug('reveive productdata from contetnScript.js:',message.data);
            planStore.product = message.data;            
            planStore.isProductPage = planStore.product.isProduct
        }
    });

    chrome.storage.local.get(['productData'], function(result) {
        console.debug('Product data from storage:', result);
        planStore.product = result.productData;            
        planStore.isProductPage = planStore.product.isProduct
        console.debug('planStore.product:', planStore.product)
    });
    
    
    checkNet();
     
    const authStore = useAuthStore();
    await authStore.checkLoginStatus();
    
    if (authStore.isLoggedIn) {
        log.debug("is logged!")
        planStore.getInfo();
    }
    app.mount("#app"); 
  }
  
  init(); 