// auth.js

export async function getAuthToken() {
  return new Promise((resolve, reject) => {
    chrome.identity.launchWebAuthFlow({
      url: 'https://accounts.google.com/o/oauth2/auth?' +
           'client_id=842612930096-qraujl77aouprlotq7n6hmjh5forebve.apps.googleusercontent.com&' +
           'response_type=token&' +
           'redirect_uri=' + encodeURIComponent(chrome.identity.getRedirectURL()) + '&' +
           'scope=email profile', // 调整 scope 至所需权限
      interactive: true
  }, function(redirectUrl) {
      if (chrome.runtime.lastError) {
          console.log("WebAuthFlow failed:", chrome.runtime.lastError);
          resolve(null);
      }
      var accessToken = new URL(redirectUrl).hash.split('&')[0].split('=')[1];
      resolve(accessToken);
  });
  
  });
}




// 从本地存储中获取 google access_token
export async function getAccessToken() {
  return getValue('access_token')
}


  // 将 access_token 保存到本地存储
  export async function saveAccessToken(access_token) {
    return setValue("access_token", access_token)
  }

// 从本地存储中获取 user
export async function getUser() {
  return getValue('user')
}

// 将 token 保存到本地存储
export async function saveUser(user) {
  return setValue("user", user)
}



export async function removeUser() {
  return removeValue("user")
}


// 从本地存储中获取 token
export async function getToken() {
    return getValue('token')
}
  
  
  export async function saveToken(token) {
    return setValue("token", token)
  }



  export async function removeToken() {
    return removeValue("token")
  }


  async function getValue(key) {
    return new Promise((resolve, reject) => {
      chrome.storage.sync.get([key], (result) => {
        if (chrome.runtime.lastError) {
          console.error('Failed to get token:', chrome.runtime.lastError);
          // alert(`Error : ${chrome.runtime.lastError}`)
          return resolve(null);
        }
        resolve(result[key]);
      });
    });
  }
  

 async function setValue(key ,value) {
  return new Promise((resolve, reject) => {
    chrome.storage.sync.set({ [key]: value }, (result) => {
      if (chrome.runtime.lastError) {
          console.error('Failed to save token:', chrome.runtime.lastError);
          // alert(`Error : ${chrome.runtime.lastError}`)
          return resolve(null);
      }
      resolve(null);
    });
  });
}

async function removeValue(key) {
  return new Promise((resolve, reject) => {
    chrome.storage.sync.remove([key], (result) => {
      if (chrome.runtime.lastError) {
          console.error('Failed to remove value:', chrome.runtime.lastError);
          // alert(`Error : ${chrome.runtime.lastError}`)
          return resolve(null);
      }
      resolve(null);
    });
  });
}