// utils/request.js

import axios from 'axios'
import { useAuthStore } from '../store/authStore.js'  // 引入authStore
import log from 'loglevel';
import { APP_ID } from '../utils/config.js';


export async function checkNet() {
  while (true) {
    try {
      await axios.get(`${import.meta.env.VITE_APP_BASE_API}/health`); // 替换为你的实际 health check 端点
      break;
    } catch (error) {
      if (error.code === 'ECONNABORTED' || error.message === 'Network Error') {
        log.error('Network error or timeout, retrying...');
      } else {
        log.error('Health check failed:', error);
        break;  // 如果错误不是网络错误或超时，那么停止重试
      }
    }
    await new Promise(r => setTimeout(r, 1000));  // 等待5秒后再次重试
  }
}


export const googleService = axios.create({
    baseURL: import.meta.env.VITE_GOOGLE_BASE_API, // 基础url，与主要API有所不同
    timeout: 60000 // 请求超时时间
  })


  googleService.interceptors.response.use(
    response => {
      if (response.status === 200) {
        return response.data
       } else {
        console.error(`Error ${response.status}: ${response.statusText}`)
        // 在这里添加你的错误处理逻辑，比如显示一个错误消息
        // alert(`Error ${error.response.status}: ${error.message}`)
        return null
      }
    },
    error => {
        if (error.response) {
            console.error(`Error ${error.response.status}: ${error.message}`)
            // alert(`Error ${error.response.status}: ${error.message}`)
            // ...
          } else {
            console.error(`Error: ${error.message}`)
            // alert(`Error: ${error.message}`)
            // ...
          }
          return null
    }
  )


const service = axios.create({
  baseURL: import.meta.env.VITE_APP_BASE_API, // 基础url，可以从环境变量中读取
  timeout: 60000 // 请求超时时间
})


// 请求拦截器
service.interceptors.request.use(
    async config => {
        const token = useAuthStore().token;
        if (token) {
          config.headers['x-token'] = token;
        }
        config.headers['app_id'] = APP_ID;
        return config;
      },
    error => {
        console.error('Request error: ', error)
        // alert('An error occurred when sending the request.')
        return null
    }
  )


  service.interceptors.response.use(
    response => {
      // 如果状态码是200，那么就返回响应数据
      if (response.status === 200) {
        if (response.data.code === 20001) {
            const authStore = useAuthStore();  // 使用authStore
            authStore.resetLoginStatus();  // 重置登录状态
            return null
          } else {
            if (response.data.code != 0) {
                console.error(`Error ${response.data.code}: ${response.data.msg}`)
                return null
            } else {
              return response.data
            }
          }
      } else {
        // 如果状态码不是200，那么就处理这个错误
        console.error(`Error ${response.status}: ${response.statusText}`)
        // 在这里添加你的错误处理逻辑，比如显示一个错误消息
        // alert(`Error ${error.response.status}: ${error.message}`)
        return null
      }
    },
    error => {
        if (error.response) {
            console.error(`Error ${error.response.status}: ${error.message}`)
            // alert(`Error ${error.response.status}: ${error.message}`)
            // ...
          } else {
            console.error(`Error: ${error.message}`)
            // alert(`Error: ${error.message}`)
            // ...
          }
          return null
    }
  )

export default service
