import { defineStore } from "pinia";
import { getPlanInfo,isPro,unsubscribe,renew } from "../api/plan.js";

export const usePlanStore = defineStore({
  id: "planStore",
  state: () => ({
    isLoading: false,
    subLoading: false,
    planInfo: null,
    pro: false,
    product: null,
    isProductPage:false
  }),
  actions: {
    async getInfo(isLoading = true) {
      if (isLoading) {
        this.isLoading = true; // Start loading
      }
    
      const data = await getPlanInfo();
      if (data && data.data) {
        this.planInfo = data.data;
        this.pro = this.planInfo.isPro;
      }
    
      if (isLoading) {
        this.isLoading = false; // Stop loading
      }
    },
    async isPro() {
      const data = await isPro();
      if (data && data.data) {
        this.pro = data.data.is_pro;
      }
    },
    async unsubscribe(param) {
      this.subLoading = true;
      const data = await unsubscribe(param);
      if (data && data.code == 0) {
        await this.getInfo()
      }
      this.subLoading = false;
    },
    async renew(param) {
      this.subLoading = true;
      let attempt = 0;
      const maxAttempts = 3;
    
      while (attempt < maxAttempts) {
        try {
          const data = await renew(param);
          if (data && data.code == 0) {
            await this.getInfo();
            this.subLoading = false;
            return true;  // 成功后返回true
          }
        } catch (error) {
          console.error("Attempt to renew failed:", error);
        }
        attempt++;
      }
    
      this.subLoading = false;
      return false;  // 所有尝试都失败后返回false
    }     
  },
});
